import {AIError} from '../../types/ai.js';
import {requireOptionalPeer} from '../requireOptionalPeer.js';
import type {AIProvider, MessageChunk, SendMessageParams, StructuredOutputParams} from '../../types/ai.js';
import {
  emptyToolAccumulator,
  handleTextDelta,
  handleToolStart,
  handleToolInputDelta,
  handleContentBlockStop,
  handleMessageStop,
} from './bedrockStreamHandlers.js';
import {mapBedrockError} from './bedrockErrorMap.js';
import {mapMessage, mapToolConfig} from './bedrockMessageMapper.js';
import {log} from '../../shared/logger.js';

export interface BedrockConfig {
  type: 'bedrock';
  modelId: string;
  region: string;
  maxTokens: number;
}

export function createBedrockProvider(config: BedrockConfig): AIProvider {
  const {BedrockRuntimeClient, ConverseStreamCommand} = requireOptionalPeer<
    typeof import('@aws-sdk/client-bedrock-runtime')
  >('@aws-sdk/client-bedrock-runtime');
  const client = new BedrockRuntimeClient({region: config.region});

  return {
    async generateStructured<T>(_params: StructuredOutputParams<T>): Promise<T> {
      throw new Error('Bedrock structured output is not yet implemented.');
    },

    async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
      const {messages, systemPrompt, tools, maxTokens} = params;

      log.info('bedrock', 'sending message', {
        modelId: config.modelId,
        messageCount: messages.length,
        hasTools: !!tools,
      });

      try {
        const command = new ConverseStreamCommand({
          modelId: config.modelId,
          system: [{text: systemPrompt}],
          messages: messages.map(mapMessage),
          inferenceConfig: {maxTokens: maxTokens ?? config.maxTokens},
          ...(tools && {toolConfig: mapToolConfig(tools)}),
        });

        const response = await client.send(command);

        if (response.stream) {
          log.info('bedrock', 'stream started');
          yield* parseStreamEvents(response.stream);
        }
      } catch (error) {
        log.error('bedrock', 'error', {error: error instanceof Error ? error.message : 'Unknown'});
        if (error instanceof AIError) throw error;
        throw mapBedrockError(error);
      }
    },
  };
#!/usr/bin/env node
// Holds every `([validated by: <test name>](path#Lnn))` citation to the test it names.
//
// Usage:
//   node scripts/check-spec-anchor-names.mjs           # report, exit 1 on any finding
//   node scripts/check-spec-anchor-names.mjs --fix     # repoint each line from the name it carries
//
// A line number is the wrong thing to cite: inserting an import above a suite moves every test below
// it, and the citation silently lands on a different, still-valid declaration. The name is what the
// author meant, so the name is what the citation records and the line becomes a derived pointer this
// script repairs. The `#Lnn` stays because the lint rule and the coverage job both index by it, and a
// citation without one marks the whole file covered rather than one test.
import {readFileSync, writeFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import process from 'node:process';
import {dirname, join, normalize} from 'node:path';
import {root} from './lib/repo-root.mjs';

const CITATION = /\[validated by(?<label>: [^\]]*)?\]\((?<path>(?:\.\.\/)+[\w./-]+?)#L(?<line>\d+)\)/g;
// Any other href shape is refused rather than ignored: the coverage job resolves `./../x` and `/x`
// to the same file and counts them, while this gate and the drift check would never have read them.
const ANY_HREF = /\[validated by(?:: [^\]]*)?\]\((?<path>[^)#\s]+)#L\d+\)/g;
// `xit`, `xdescribe` and `.skip` declare a test that never runs, which validates nothing.
const DECLARATION = /^\s*(?:f?it|f?describe|test)\(\s*(['"`])((?:\\.|(?!\1).)*)\1/;
const SKIPPED = /^\s*(?:x(?:it|describe|test)|(?:it|describe|test)\.skip)\(\s*(['"`])((?:\\.|(?!\1).)*)\1/;
const TEST_FILE = /\.(?:test|spec)\.[cm]?[jt]sx?$/;

const cache = new Map();
const args = process.argv.slice(2);
const fix = args.includes('--fix');
const named = args.filter(arg => !arg.startsWith('--'));
const findings = [];
let checked = 0;
let repaired = 0;

for (const spec of named.length > 0 ? named : specs()) {
  const source = readFileSync(join(root, spec), 'utf8');
  const specDir = dirname(spec);
  let changed = false;

  for (const match of source.matchAll(ANY_HREF)) {
    if (!match.groups.path.startsWith('../')) {
      findings.push(`${spec}: href "${match.groups.path}" must be relative and start with ../`);
    }
  }

  const rewritten = source.replace(CITATION, (whole, label, path, line, ...rest) => {
    const groups = rest[rest.length - 1];
    const target = normalize(join(specDir, groups.path));
    if (!TEST_FILE.test(target)) return whole;

    checked += 1;
    const declarations = declarationsIn(target);
    if (declarations === null) {
      findings.push(`${spec}: ${groups.path} does not exist`);
      return whole;
    }

    const named = groups.label ? groups.label.slice(2) : null;
    const atLine = declarations.find(declaration => declaration.line === Number(groups.line));

    const skipped = declarations.find(d => d.skipped && (d.name === named || d.line === Number(groups.line)));
    if (skipped) {
      findings.push(`${spec}: cites "${skipped.name}" at ${groups.path}#L${skipped.line}, which is skipped and validates nothing`);
      return whole;
    }

    if (named === null) {
      if (!atLine) {
        findings.push(`${spec}: ${groups.path}#L${groups.line} is not a declaration, so no name can be read from it`);
        return whole;
      }
      if (nameIsAmbiguous(declarations, atLine.name)) {
        findings.push(ambiguity(spec, groups.path, atLine.name, declarations));
        return whole;
      }
      if (!fix) {
        findings.push(`${spec}: ${groups.path}#L${groups.line} carries no test name`);
        return whole;
      }
# AGENTS.md

## Context Loading Order

Agents should read files in this order to understand the HAL Engine codebase:

1. **README.md** - Overview, features, quick start, and project structure
2. **package.json** - Dependencies, scripts, tech stack validation
3. **tsconfig.json** - TypeScript configuration and compilation targets
4. **src/index.ts** - Public API exports and module surface
5. **src/config.ts** - Main factory function `createHalEngine()` and configuration schema
6. **src/types/** - Core type definitions (ai.ts, session.ts, messages.ts, auth.ts, sessionStore.ts)
7. **src/providers/** - AI provider implementations (bedrock, vertex, openai, anthropic, mock)
8. **src/infrastructure/** - Support layers (builders, stores, parsers)
9. **src/orchestration/** - Business logic (chatOrchestrator, tools, context management)
10. **src/transport/** - Server setup (Express app, WebSocket, routes)
11. **specs/** - Normative specs (architecture, WebSocket protocol, providers, tool responses)
12. **adrs/** - Architecture Decision Records
13. **docs/** - How-to guides, coding practices, and research spikes under docs/spikes/
14. **.specify/spec.md** - Repo-level system spec (exempt from the spec header table convention)

## Workflow Commands

### Development
```bash
npm run dev          # Start example/server.ts with hot reload (tsx watch)
npm run typecheck    # Run TypeScript type checking without emitting
```

### Building
```bash
npm run build        # Compile TypeScript to dist/ (tsc)
npm start            # Run compiled JavaScript from dist/index.js
```

### Testing
```bash
npm test             # Run Jest test suite
# Tests use ts-jest for TypeScript compilation
# Configuration: jest.config.js
```

### Code Quality
```bash
npm run eslint       # Run ESLint with max-warnings 0 (zero-tolerance)
npm run prettier     # Format all src/**/*.ts with Prettier
npm run prettier:check  # Check formatting without writing
```

### All Checks (Recommended Pre-Commit)
```bash
npm run verify
```

That is the blocking set `.github/workflows/ci.yml`'s `verify` job runs on every
pull request, in the same order, and `scripts/verify-script.test.ts` fails if the
two stop agreeing - so this command cannot quietly become a subset of what CI
demands. Two gates in that job are missing from it because both diff against
`origin/main` and neither runs the same way on a checkout: the spec anchor check
and the changelog check.

Two further CI jobs are worth running locally before a release or a change that
touches packaging: `npm run check:build-chain` (audit and action pins) and
`npm run smoke` (packs the tarball and installs it outside this tree).

## Spec Header Table

Every `specs/*/spec.md` opens with its title, then a two-column header table,
and carries a lead paragraph of prose before its first `##` section:

```markdown
# <spec title>

| Field  | Value                  |
| ------ | ---------------------- |
| Issue  | re-cinq/HALEngine#<n> |
| Status | Draft                  |

<lead paragraph>
```

The lead paragraph does not have to sit immediately after the table: a spec
carrying a metadata block of its own may place that block between the two. What
the convention requires is that prose, rather than a section heading, follows
the header material, and that the prose runs to at least 40 characters -
anything shorter is reported as no lead paragraph at all.

`Issue` names the issue the spec was written against, or `n/a` for the specs
that predate this convention.

`Status` is one of `Draft`, `In Progress` or `Shipped`. It is not a mood, and
it is not a claim about how finished the feature is: it is the spec's own
test-citation coverage. No testable statement cited is `Draft`, some cited is
`In Progress`, all cited is `Shipped`. A spec describing shipped, working
behaviour still reads `Draft` until its statements cite the tests that
validate them.

A spec that should no longer be graded takes a terminal value instead. The
parser buckets roughly sixteen labels into five buckets, and the two terminal
ones skip the coverage check whatever the citation count:

